// Caller must allocate storage larger than the expected handle
// and set handle_bytes to the buffer size.
union handle_buf {
    struct file_handle h;
    char pad[128];
};

union handle_buf storage;
int mount_id;
const char* path = "/etc/passwd";

// Initialize buffer size
storage.h.handle_bytes = sizeof(storage);

int ret = name_to_handle_at(
    AT_FDCWD,
    path,
    &storage.h,
    &mount_id,
    0
);

if (ret == -1) {
    // Handle error (e.g., ENOSYS, EOVERFLOW if handle_bytes too small)
}

